window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[179]={"id":"179","numero":179,"titre":"Risques sanitaires liés à l'eau et à l'alimentation · TIAC","objectifs":[{"id":"179-1","rang":"B","rubrique":"Étiologies","titre":"Connaître les parasitoses transmises par la consommation d’eau","contenu":"<p><span class=\"kw-clinique\">Les</span> parasitoses transmises par la <span class=\"kw-def\">consommation d'eau</span> sont quasi exclusivement des <strong><span class=\"kw-etio\">protozooses</span></strong>, à transmission <span class=\"kw-clinique\">féco-orale</span>. Quatre agents sont à connaître.</p>\n      <table >\n        <thead><tr><th>Parasitose</th><th>Agent &amp; réservoir</th><th>Clinique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Amoebose</span></strong></td>\n            <td><span class=\"kw-etio\">Entamoeba histolytica</span> ; protozoose à réservoir <strong>strictement humain</strong>, cosmopolite</td>\n            <td>Surtout dans <span class=\"kw-clinique\">les</span> zones à <span class=\"kw-alerte\">hygiène pauvre</span> ; amoebose intestinale</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Cryptosporidiose</span></strong></td>\n            <td><span class=\"kw-etio\">Cryptosporidium</span> ; protozoose cosmopolite ; transmission <span class=\"kw-clinique\">féco-orale</span> ou <span class=\"kw-clinique\">manu-portée</span></td>\n            <td><span class=\"kw-clinique\">Diarrhée aiguë cholérigorme</span> ou <span class=\"kw-clinique\">chronique</span> + <span class=\"kw-clinique\">malabsorption</span> chez l'<span class=\"kw-alerte\">immunodéprimé</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Giardiose</span></strong></td>\n            <td><span class=\"kw-etio\">Giardia intestinalis</span> ; réservoir <strong>strictement humain</strong> ; transmission féco-orale ou <span class=\"kw-clinique\">relation sexuelle (HSH)</span></td>\n            <td>Souvent <span class=\"kw-clinique\">asymptomatique</span> ; possible <span class=\"kw-clinique\">diarrhée chronique</span> de l'enfant → <span class=\"kw-alerte\">malabsorption / malnutrition</span> (pays pauvres)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Toxoplasmose</span></strong></td>\n            <td><span class=\"kw-etio\">Toxoplasma gondii</span> ; protozoose cosmopolite dont le <strong>chat est l'hôte définitif</strong></td>\n            <td>Symptomatique dans <span class=\"kw-chiffre\">≈ 20 %</span> des cas, tableau aspécifique (<span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">polyadénopathies</span>…)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 172 — Parasitose digestive · 175 — Voyage en pays tropical</em></p>","frequence":0},{"id":"179-2","rang":"B","rubrique":"Étiologies","titre":"Connaître les parasitoses transmises par les aliments","contenu":"<p><span class=\"kw-clinique\">Les</span> parasitoses d'origine <span class=\"kw-def\">alimentaire</span> sont surtout des <strong><span class=\"kw-etio\">helminthoses</span></strong>, acquises en ingérant viande ou poisson <span class=\"kw-alerte\">crus ou insuffisamment cuits</span>.</p>\n      <table >\n        <thead><tr><th>Parasitose</th><th>Mode de contamination</th><th>Clinique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Taeniasis</span></strong></td>\n            <td>Ingestion de viande parasitée (bœuf, porc)</td>\n            <td>Téniasis intestinal — <em>détaillé à l'item 172</em></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Trichinellose</span></strong></td>\n            <td>Zoonose cosmopolite ; l'homme est un <strong>hôte accidentel</strong> en mangeant de la <span class=\"kw-alerte\">viande crue ou peu cuite</span> contenant des <span class=\"kw-etio\">larves enkystées</span> → migration vers <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">muscles striés</span></td>\n            <td><span class=\"kw-clinique\">Polymyosite fébrile</span> + <span class=\"kw-clinique\">œdème de la face</span> ; <span class=\"kw-alerte\">évolution grave voire mortelle</span> à la phase précoce de dissémination larvaire</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Anisakiase</span></strong></td>\n            <td>Zoonose des <strong>mers froides</strong> ; ingestion de <span class=\"kw-alerte\">poisson infesté de larves</span> (cru, mariné ou mal cuit)</td>\n            <td>Symptômes digestifs précoces (<span class=\"kw-clinique\">gastralgies</span>, <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vomissements</span>) ± <span class=\"kw-clinique\">réactions allergiques</span> intestinales ou généralisées</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 172 — Parasitose digestive · 173 — Zoonose</em></p>","frequence":0},{"id":"179-3","rang":"A","rubrique":"Définition","titre":"Savoir préciser les principaux risques liés à la consommation d’eau","contenu":"<p>On distingue <strong>quatre types de risques sanitaires</strong> liés à l'eau et à l'alimentation : <span class=\"kw-def\">biologiques</span> (<span class=\"kw-etio\">bactérien</span>, viral, parasitaire, fongique, ATNC), <span class=\"kw-def\">physiques</span> (noyade, brûlure, radioactivité, phénomènes naturels), <span class=\"kw-def\">chimiques</span> (nitrates, métaux lourds, pesticides, additifs…) et <span class=\"kw-def\">autres</span> (<span class=\"kw-ci\">allergie</span>, troubles nutritifs, réservoir de vecteurs). Pour l'eau, on retient trois familles.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Risques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Risques physiques</strong></td>\n            <td><strong>Brûlures :</strong> à l'eau chaude, surtout l'enfant de <span class=\"kw-chiffre\">1 à 4 ans</span> (accidents domestiques)<br>\n            <strong>Noyades :</strong> en eau douce ou en eau de mer, lors d'activités de loisir ou professionnelles<br>\n            <strong>Activité subaquatique :</strong> risques liés à la plongée de loisir ou professionnelle</td>\n          </tr>\n          <tr>\n            <td><strong>Risques chimiques</strong></td>\n            <td><strong>Pollution minérale :</strong> éléments nocifs en excès — <span class=\"kw-alerte\">métaux lourds</span> (plomb, mercure, arsenic, chrome)<br>\n            <strong>Pollutions organiques :</strong> <span class=\"kw-etio\">pesticides</span>, <span class=\"kw-etio\">nitrites</span>… → <span class=\"kw-alerte\">méthémoglobinémie</span>, <span class=\"kw-alerte\">saturnisme</span>, neurotoxicité, cancérogenèse</td>\n          </tr>\n          <tr>\n            <td><strong>Risques <span class=\"kw-etio\">infectieux</span></strong></td>\n            <td><strong>Bactéries :</strong> <span class=\"kw-etio\">Salmonella</span> typhi/paratyphi (typhoïde), <span class=\"kw-etio\">Vibrio cholerae</span> (choléra), <span class=\"kw-etio\">E. coli</span>, <span class=\"kw-etio\">Shigella</span>, <span class=\"kw-etio\">Campylobacter</span>, <span class=\"kw-etio\">Yersinia</span><br>\n            <strong>Virus :</strong> <span class=\"kw-etio\">hépatites A et E</span>, <span class=\"kw-etio\">rotavirus</span>, norovirus<br>\n            <strong>Parasites :</strong> amoebose, cryptosporidiose, giardiose (cf. obj-0)<br>\n            <strong>ATNC :</strong> <span class=\"kw-etio\">prions</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La <span class=\"kw-clinique\">diarrhée</span> est une conséquence fréquente des pathologies hydriques — c'est la <strong>2ᵉ cause de <span class=\"kw-def\">mortalité</span> de l'enfant de <span class=\"kw-chiffre\">moins de 5 ans</span></strong>. En Europe, la sécurité sanitaire est encadrée par le « <span class=\"kw-def\">paquet hygiène</span> » (règlements européens).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales · 176 — <span class=\"kw-clinique\">Diarrhée</span> infectieuse · 175 — Voyage en pays tropical</em></p>","frequence":0},{"id":"179-4","rang":"B","rubrique":"Définition","titre":"Savoir préciser les sources de pollution de l’eau","contenu":"<p>La <span class=\"kw-def\">pollution de l'eau</span> provient de trois sources principales, selon l'activité humaine en cause.</p>\n      <table >\n        <thead><tr><th>Source</th><th>Origine</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Pollution domestique</span></strong></td>\n            <td>Liée à l'<strong>utilisation quotidienne de l'eau au domicile</strong> : eaux de toilettes et de lavage contenant détergents, produits ménagers, graisses et résidus</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Pollution agricole</span></strong></td>\n            <td>Liée à l'<strong>exploitation agricole intensive</strong> (élevage et cultures végétales) : déchets physiologiques de l'élevage, engrais, herbicides, <span class=\"kw-etio\">pesticides</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Pollution industrielle</span></strong></td>\n            <td>Liée aux <strong>rejets de tous types d'industries</strong> : effluents industriels, chauffage, stagnation de l'eau, hôpitaux</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"179-5","rang":"A","rubrique":"Définition","titre":"Connaître les mesures de prévention des risques sanitaires liés à l’eau","contenu":"<p>La prévention repose sur la définition de <strong><span class=\"kw-def\">critères de</span> potabilité</strong> et sur <strong>trois axes prioritaires</strong> d'action.</p>\n      <p><strong><span class=\"kw-def\">Critères de potabilité de l'eau</span></strong> destinée à la consommation humaine :</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Exigence</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Microbiologiques</strong></td><td>Absence de <span class=\"kw-bio\">coliformes</span> (dont <span class=\"kw-etio\">E. coli</span>), d'<span class=\"kw-bio\">entérocoques</span> et de <span class=\"kw-bio\">bactéries sulfito-réductrices</span></td></tr>\n          <tr><td><strong>Organoleptiques</strong></td><td>Eau claire, fraîche, sans odeur</td></tr>\n          <tr><td><strong>Physicochimiques</strong></td><td>Absence d'<span class=\"kw-alerte\">éléments chimiques toxiques</span> (métaux lourds, substances organiques, produits de désinfection)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Trois axes prioritaires de prévention :</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Assainissement</span></strong> — collecte, traitement et évacuation des déchets liquides et solides, y compris <span class=\"kw-clinique\">les</span> déchets physiologiques humains.</li>\n        <li><strong><span class=\"kw-def\">Garantie de la potabilité</span></strong> — gestion du « capital eau » : protection des réserves naturelles et gestion optimale du cycle de l'eau.</li>\n        <li><strong><span class=\"kw-def\">Contrôle de la potabilité</span></strong> — respect des normes nationales et internationales, contrôles réglementaires à toutes <span class=\"kw-clinique\">les</span> étapes.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Acteurs.</strong> La <strong><span class=\"kw-def\">surveillance</span></strong> de la qualité de l'eau est assurée par l'<span class=\"kw-def\">ARS</span> ; l'<strong>analyse</strong> est réalisée par des <span class=\"kw-def\">laboratoires agréés Cofrac</span>. Le niveau de risque dépend du pays → importance des <span class=\"kw-clinique\">conseils aux voyageurs</span> (consommation d'eau, baignades, marche pieds nus en eau stagnante).\n      </div>","frequence":0},{"id":"179-6","rang":"A","rubrique":"Définition","titre":"Savoir préciser les principaux risques liés à l’alimentation","contenu":"<p>Pour l'alimentation, <strong>deux risques prédominants</strong> sont à distinguer.</p>\n      <table >\n        <thead><tr><th>Risque</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Nutrition</span></strong></td>\n            <td>Troubles nutritifs (<span class=\"kw-clinique\">obésité</span>, <span class=\"kw-clinique\">anorexie</span>) ; <span class=\"kw-clinique\">allergies alimentaires</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Salubrité alimentaire</span></strong></td>\n            <td><strong>Risque <span class=\"kw-etio\">infectieux</span> :</strong> sur toute la chaîne alimentaire (matière première → distribution, y compris pathologies des mains sales) — conventionnel (<span class=\"kw-etio\">bactérien</span>, parasitaire, fongique, viral, toxinique) ou non conventionnel (<span class=\"kw-etio\">prion</span>)<br>\n            <strong>Risque chimique :</strong> additifs, polluants, antibiotiques, toxiques<br>\n            <strong>Risque physique :</strong> radioactivité</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales</em></p>","frequence":0},{"id":"179-7","rang":"A","rubrique":"Définition","titre":"Savoir définir une toxi-infection alimentaire collective (TIAC) et connaître les différentes symptomatologies de TIAC","contenu":"<p>Une <strong><span class=\"kw-etio\">toxi-infection alimentaire collective (TIAC)</span></strong> se définit par l'apparition d'<strong><span class=\"kw-chiffre\">≥ 2 cas</span></strong> d'une symptomatologie, en général digestive, dont on peut rapporter la cause à une <strong>même origine alimentaire</strong>. La TIAC est une <strong><span class=\"kw-alerte\">maladie à déclaration obligatoire (MDO)</span></strong>.</p>\n      <p><strong>Cause</strong> — consommation d'aliments contaminés, soit par des bactéries / virus / parasites, soit par des <span class=\"kw-def\">toxines</span> bactériennes. La <span class=\"kw-def\">toxinogénèse</span> a lieu :</p>\n      <ul>\n        <li>soit <strong>dans l'aliment</strong> — <span class=\"kw-etio\">S. aureus</span>, toxine thermostable de <span class=\"kw-etio\">B. cereus</span>, <span class=\"kw-etio\">Clostridium botulinum</span> ;</li>\n        <li>soit <strong>dans la lumière digestive</strong> — toxine thermolabile de <span class=\"kw-etio\">B. cereus</span>, <span class=\"kw-etio\">C. perfringens</span>.</li>\n      </ul>\n      <p>Aliments <span class=\"kw-clinique\">les</span> plus incriminés : <strong>viandes de volaille, aliments à base d'œufs, fruits de mer</strong>. Facteurs favorisants : <span class=\"kw-alerte\">rupture de la chaîne du froid</span>, erreurs de préparation, délai trop long entre préparation et consommation.</p>\n      <p><strong>Symptomatologies de TIAC</strong> :</p>\n      <table >\n        <thead><tr><th>Tableau</th><th>Clinique &amp; incubation</th><th>Germes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Entéro-toxinogène</strong> (cholériforme)</td>\n            <td><span class=\"kw-clinique\">Diarrhée liquide abondante</span> + <span class=\"kw-clinique\">vomissements</span> + <strong>absence de <span class=\"kw-clinique\">fièvre</span></strong><br>Incubation <span class=\"kw-chiffre\">courte</span> (quelques heures)</td>\n            <td><span class=\"kw-etio\">Norovirus</span>, <span class=\"kw-etio\">C. perfringens</span>, <span class=\"kw-etio\">B. cereus</span>, <span class=\"kw-etio\">E. coli</span> entérotoxinogène</td>\n          </tr>\n          <tr>\n            <td><strong>Entéro-invasif</strong> (dysentérique)</td>\n            <td><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-clinique\">diarrhée afécale glairosanglante</span> + <span class=\"kw-clinique\">douleurs abdominales</span><br>Incubation <span class=\"kw-chiffre\">longue</span> (<span class=\"kw-chiffre\">24 à 72 h</span>)</td>\n            <td><span class=\"kw-etio\">Salmonella</span>, <span class=\"kw-etio\">Campylobacter jejuni</span>, <span class=\"kw-etio\">Vibrio parahaemolyticus</span>, <span class=\"kw-etio\">E. coli</span> entéro-invasif, <span class=\"kw-etio\">Yersinia</span>, <span class=\"kw-etio\">Shigella</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Hépatite</span> aiguë</strong></td>\n            <td>Tableau d'<span class=\"kw-etio\">hépatite</span> <span class=\"kw-etio\">virale</span> aiguë</td>\n            <td><span class=\"kw-etio\">VHA</span>, <span class=\"kw-etio\">VHE</span></td>\n          </tr>\n          <tr>\n            <td><strong>Expression extradigestive / neurologique</strong></td>\n            <td>Manifestations cutanées (<span class=\"kw-clinique\">érythème</span>, bouffées vasomotrices) ; <span class=\"kw-alerte\">manifestations neurologiques</span> (botulisme : diplopie, paralysie flasque descendante)</td>\n            <td><span class=\"kw-etio\">C. botulinum</span>, neurotoxines de dinoflagellés, histamine (poisson avarié)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant.</strong> Des cas <strong>très groupés dans le temps</strong> orientent vers une incubation <span class=\"kw-chiffre\">courte</span> (source ponctuelle) ; des cas <strong>dispersés</strong> après le repas commun orientent vers une incubation <span class=\"kw-chiffre\">longue</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 176 — <span class=\"kw-clinique\">Diarrhée</span> infectieuse</em></p>","frequence":0},{"id":"179-8","rang":"A","rubrique":"Étiologies","titre":"Connaître les agents pathogènes responsable de TIAC","contenu":"<p><span class=\"kw-clinique\">Les</span> agents responsables de TIAC se classent selon leur <strong>mécanisme</strong> et leur <strong>durée d'incubation</strong>.</p>\n      <table >\n        <thead><tr><th>Agent</th><th>Incubation</th><th>Clinique</th><th>Aliment vecteur</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Salmonella enterica</span></strong> non typhi</td>\n            <td><span class=\"kw-chiffre\">12 à 24 h</span></td>\n            <td><span class=\"kw-clinique\">Diarrhée aiguë fébrile</span></td>\n            <td>Viandes, volailles, œufs, fruits de mer peu/pas cuits</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Staphylococcus aureus</span></strong></td>\n            <td><span class=\"kw-chiffre\">2 à 4 h</span></td>\n            <td><span class=\"kw-clinique\">Vomissements</span>, <span class=\"kw-clinique\">douleurs abdominales</span>, <span class=\"kw-clinique\">diarrhée</span>, <strong>absence de <span class=\"kw-clinique\">fièvre</span></strong></td>\n            <td>Lait et dérivés, plats cuisinés la veille ; porteur sain / staphylococcie cutanée</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Clostridium perfringens</span></strong></td>\n            <td><span class=\"kw-chiffre\">8 à 24 h</span></td>\n            <td><span class=\"kw-clinique\">Diarrhée aiguë</span>, absence de <span class=\"kw-clinique\">fièvre</span></td>\n            <td>Plats cuisinés la veille, réfrigération insuffisante, restauration collective</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Norovirus</span></strong></td>\n            <td><span class=\"kw-chiffre\">24 à 48 h</span></td>\n            <td><span class=\"kw-clinique\">Vomissements</span>, <span class=\"kw-clinique\">douleurs abdominales</span>, <span class=\"kw-clinique\">diarrhée</span> peu/pas fébrile</td>\n            <td>Coquillages, crustacés, crudités</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Clostridium botulinum</span></strong></td>\n            <td><span class=\"kw-chiffre\">12 à 72 h</span></td>\n            <td><span class=\"kw-alerte\">Botulisme</span> (voir encadré ci-dessous)</td>\n            <td>Jambon, conserves artisanales</td>\n          </tr>\n          <tr>\n            <td><strong>Intoxication histaminique</strong></td>\n            <td><span class=\"kw-chiffre\">10 min à 1 h</span></td>\n            <td>Troubles vasomoteurs (face, cou), <span class=\"kw-clinique\">céphalées</span>, troubles digestifs</td>\n            <td>Poisson mal conservé (thon, maquereau)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Le tableau clinique permet de séparer <span class=\"kw-clinique\">les</span> agents <strong>entéro-invasifs</strong> (incubation longue, <span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-clinique\">diarrhée</span> glairosanglante : <span class=\"kw-etio\">Salmonella</span>, <span class=\"kw-etio\">Shigella</span>, <span class=\"kw-etio\">Campylobacter jejuni</span>, <span class=\"kw-etio\">Yersinia enterocolitica</span>, <span class=\"kw-etio\">Listeria</span>) des agents <strong>entéro-toxinogènes</strong> (incubation courte, toxine préformée, sans <span class=\"kw-clinique\">fièvre</span> : <span class=\"kw-etio\">S. aureus</span>, <span class=\"kw-etio\">B. cereus</span>, <span class=\"kw-etio\">C. perfringens</span>).</p>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> — TIAC à <span class=\"kw-etio\">E. coli</span> entérohémorragique (O157:H7).</strong> Enfant de <span class=\"kw-chiffre\">moins de 5 ans</span> (1ʳᵉ cause d'<span class=\"kw-etio\">IRA</span> organique avant <span class=\"kw-chiffre\">3 ans</span>), après produits peu/pas cuits (lait, viande). <span class=\"kw-clinique\">Évolution</span> en 3 phases : <span class=\"kw-clinique\">phase digestive</span> (<span class=\"kw-clinique\">diarrhée</span> sanglante) → <span class=\"kw-clinique\">phase hématologique</span> (microangiopathie <span class=\"kw-etio\">thrombotique</span> : <span class=\"kw-bio\">anémie hémolytique</span> + <span class=\"kw-bio\">thrombopénie</span>) → <span class=\"kw-alerte\">phase rénale</span> (<span class=\"kw-etio\">IRA</span> oligoanurique, dialyse dans <span class=\"kw-chiffre\">50 %</span> des cas). PEC <span class=\"kw-ttt\">symptomatique</span> ± <span class=\"kw-ttt\">épuration extra-rénale</span> ; prévention = interdiction des laitages non pasteurisés et des viandes crues avant <span class=\"kw-chiffre\">5 ans</span>.\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Botulisme.</strong> Toxine bloquant <span class=\"kw-clinique\">les</span> synapses cholinergiques. Phase d'état : <span class=\"kw-clinique\">syndrome parasympathicolytique</span> (mydriase, sécheresse buccale, <span class=\"kw-clinique\">dysphagie</span>, <span class=\"kw-clinique\">constipation</span>, <span class=\"kw-clinique\">dysurie</span>) + <span class=\"kw-clinique\">paralysie descendante</span> — mais <strong>absence de <span class=\"kw-clinique\">fièvre</span></strong>, <strong>vigilance normale</strong>, pas de <span class=\"kw-clinique\">syndrome méningé</span>. <span class=\"kw-alerte\">Réanimation + sérothérapie</span> si atteinte respiratoire.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant clé.</strong> Incubation <span class=\"kw-chiffre\">&lt; 24 h</span> + <span class=\"kw-clinique\">vomissements</span> <strong>sans <span class=\"kw-clinique\">fièvre</span></strong> → <span class=\"kw-etio\">toxine préformée</span> (S. aureus, B. cereus). Incubation <span class=\"kw-chiffre\">&gt; 24 h</span> + <strong><span class=\"kw-clinique\">fièvre</span></strong> → <span class=\"kw-etio\">infection entéro-invasive</span> (<span class=\"kw-etio\">Salmonella</span>, Shigella, Campylobacter).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 176 — <span class=\"kw-clinique\">Diarrhée</span> infectieuse · 286 — <span class=\"kw-clinique\">Diarrhée</span> aiguë - <span class=\"kw-clinique\">déshydratation</span></em></p>","frequence":0},{"id":"179-9","rang":"A","rubrique":"Définition","titre":"Connaître les modalités de détection et de signalement d’une suspicion de TIAC","contenu":"<p>Devant une suspicion de TIAC, deux temps : <strong>détecter</strong> puis <strong>signaler</strong> sans délai.</p>\n      <p><strong><span class=\"kw-def\">Détecter</span></strong> — réunir trois éléments :</p>\n      <ul>\n        <li>une <span class=\"kw-clinique\">symptomatologie compatible</span> avec une TIAC (forme digestive ± extradigestive) ;</li>\n        <li>au moins <strong><span class=\"kw-chiffre\">2 cas groupés</span></strong> dans le temps et l'espace (la « notion de cas » est définie sur la symptomatologie) ;</li>\n        <li>une <strong>origine alimentaire commune</strong>.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Signaler</span></strong> — le <span class=\"kw-def\">signalement</span> est une <strong><span class=\"kw-alerte\">procédure d'urgence et d'alerte, sans délai</span></strong> :</p>\n      <table >\n        <thead><tr><th>Question</th><th>Réponse</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Comment ?</strong></td><td>Par <strong>tout moyen approprié</strong> — téléphone, fax</td></tr>\n          <tr><td><strong>À qui ?</strong></td><td>Au médecin de l'<span class=\"kw-def\">ARS</span> (car MDO) <strong>et</strong> à la <span class=\"kw-def\">DDPP</span> (direction départementale de la protection des populations)</td></tr>\n          <tr><td><strong>Ensuite ?</strong></td><td><span class=\"kw-def\">Notification</span> de la déclaration via un formulaire dédié à l'<span class=\"kw-def\">ARS</span></td></tr>\n        </tbody>\n      </table>\n      <p>Conserver tous <span class=\"kw-clinique\">les</span> restes des derniers repas à <span class=\"kw-chiffre\">4 °C</span> pour les mettre à disposition de la DDPP.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Ne pas confondre le <strong><span class=\"kw-def\">signalement</span></strong> (immédiat, <span class=\"kw-alerte\">urgence</span>, par tout moyen) et la <strong>notification</strong> (différée, sur formulaire dédié).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 181 — Sécurité sanitaire des produits - Veille sanitaire</em></p>","frequence":3},{"id":"179-10","rang":"B","rubrique":"Définition","titre":"Connaître les différentes étapes d’une investigation de TIAC","contenu":"<p>L'invest<span class=\"kw-chiffre\">iga</span>tion d'une TIAC suit une <strong>séquence de 8 étapes</strong>, coordonnée par l'<span class=\"kw-def\">ARS</span> et la <span class=\"kw-def\">DDPP</span>.</p>\n      <table >\n        <thead><tr><th>#</th><th>Étape</th><th>Acteur</th><th>Finalité</th></tr></thead>\n        <tbody>\n          <tr><td>1</td><td><strong>Définition du cas</strong></td><td>Médecin signalant + <span class=\"kw-def\">ARS</span></td><td>Dénombrement ; orienter <span class=\"kw-clinique\">les</span> invest<span class=\"kw-chiffre\">iga</span>tions</td></tr>\n          <tr><td>2</td><td><strong>Recensement des cas</strong></td><td><span class=\"kw-def\">ARS</span></td><td>Préparer l'enquête alimentaire</td></tr>\n          <tr><td>3</td><td><strong>Conservation des restes &amp; plats témoins</strong></td><td>DDPP / <span class=\"kw-def\">ARS</span></td><td>Préparer l'enquête microbiologique</td></tr>\n          <tr><td>4</td><td><strong>Enquête alimentaire</strong></td><td><span class=\"kw-def\">ARS</span></td><td>Identifier l'aliment responsable</td></tr>\n          <tr><td>5</td><td><strong>Prélèvements microbiologiques</strong></td><td>DDPP</td><td>Identifier le micro-organisme</td></tr>\n          <tr><td>6</td><td><strong>Étude épidémiologique</strong></td><td><span class=\"kw-def\">ARS</span></td><td>Confirmer l'hypothèse (cohorte / cas-témoins)</td></tr>\n          <tr><td>7</td><td><strong>Enquête sanitaire</strong></td><td>DDPP</td><td>Comprendre l'origine ; actions correctives</td></tr>\n          <tr><td>8</td><td><strong>Rapport final</strong></td><td><span class=\"kw-def\">ARS</span></td><td>Traçabilité, retour d'expérience</td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> invest<span class=\"kw-chiffre\">iga</span>tions s'articulent autour de <strong>trois enquêtes</strong>, réalisées sous l'autorité du médecin inspecteur de l'<span class=\"kw-def\">ARS</span> :</p>\n      <table >\n        <thead><tr><th>Enquête</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Clinique / épidémiologique</span></strong></td>\n            <td>Recensement immédiat des cas et des sujets indemnes → calcul du <span class=\"kw-bio\">taux d'attaque</span> ; distribution des cas dans le <strong>temps</strong> et l'<strong>espace</strong> ; construction d'une <strong>courbe épidémique</strong> (un <span class=\"kw-clinique\">pic</span> signe une source ponctuelle) ; estimation de la durée moyenne d'incubation</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Alimentaire</span></strong></td>\n            <td>Menus détaillés des <span class=\"kw-chiffre\">3 repas</span> précédant la contamination présumée<br>\n            <strong>Collectivité &lt; 30 :</strong> <span class=\"kw-def\">étude de cohorte</span> → <span class=\"kw-bio\">risque relatif (RR)</span> par aliment ; <strong>RR &gt; 1</strong> = aliment suspect<br>\n            <strong>Collectivité &gt; 30 :</strong> <span class=\"kw-def\">étude cas-témoins</span> → <span class=\"kw-bio\">odds ratio (OR)</span> ; <strong>OR &gt; 1</strong> = aliment suspect</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Microbiologique</span></strong></td>\n            <td>Orientée par <span class=\"kw-clinique\">les</span> enquêtes épidémiologique et alimentaire ; prélèvements chez le patient (<span class=\"kw-bio\">selles</span>, <span class=\"kw-bio\">sang</span>, <span class=\"kw-clinique\">vomissements</span>) et sur les restes / plats témoins ; l'agent n'est retrouvé dans les aliments que dans <span class=\"kw-chiffre\">¼ des TIAC</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Garder un <strong>plat témoin</strong> et <strong>notifier</strong> <span class=\"kw-clinique\">les</span> cas ne sont <span class=\"kw-alerte\">PAS des mesures de prévention primaire</span> — ils ne s'appliquent qu'une fois la TIAC déclarée.\n      </div>","frequence":7},{"id":"179-11","rang":"A","rubrique":"Définition","titre":"Connaître les mesures de prévention des TIAC","contenu":"<p>La prévention des TIAC repose sur la <strong><span class=\"kw-def\">surveillance</span> du personnel</strong>, des <strong>règles d'hygiène</strong> et le <strong>contrôle</strong> de la restauration collective.</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Surveillance</span></strong></td>\n            <td><span class=\"kw-def\">Surveillance</span> médicale du personnel — <span class=\"kw-alerte\">éviction</span> des sujets présentant une infection cutanée, pharyngée ou digestive</td>\n          </tr>\n          <tr>\n            <td><strong>Règles d'hygiène</strong></td>\n            <td><strong>Lieux :</strong> hygiène sur <span class=\"kw-clinique\">les</span> lieux d'abattage, de pêche, de récolte<br>\n            <strong>Transport :</strong> strict respect de la <span class=\"kw-alerte\">chaîne du froid</span><br>\n            <strong>Cuisines :</strong> principe de la <strong>« marche en avant »</strong> — aucun <span class=\"kw-def\">contact</span> entre le secteur propre (préparation) et le secteur souillé<br>\n            <strong>Personnel :</strong> éducation sanitaire de la chaîne alimentaire</td>\n          </tr>\n          <tr>\n            <td><strong>Contrôle</strong></td>\n            <td>Analyses microbiologiques systématiques d'échantillons des aliments servis en restauration collective, par l'<span class=\"kw-def\">ARS</span>, <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">DSV</span> (services vétérinaires) et la <span class=\"kw-def\">DGCCRF</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Le système <strong><span class=\"kw-def\">HACCP</span></strong> (Hazard Analysis Critical Control Point) est une mesure <strong>a priori</strong> ; lors de l'enquête sanitaire, la DDPP / EOH ne fait que <strong>vérifier sa mise en place</strong>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège annale.</strong> NE SONT PAS des mesures de prévention <strong>primaire</strong> (appliquées seulement si TIAC avérée/déclarée) : garder un <strong>repas témoin</strong> en collectivité ; <strong>notifier</strong> <span class=\"kw-clinique\">les</span> cas à l'<span class=\"kw-def\">ARS</span>.\n      </div>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>MDO :</strong> la <span class=\"kw-def\">TIAC</span> est une <span class=\"kw-alerte\">maladie à déclaration obligatoire</span> — <span class=\"kw-def\">signalement</span> <span class=\"kw-alerte\">sans délai</span> (procédure d’<span class=\"kw-alerte\">urgence</span> et d’alerte).<br><strong>Signaler :</strong> par <strong>tout moyen approprié</strong> (<span class=\"kw-chiffre\">téléphone</span>, fax) au médecin de l’<span class=\"kw-def\">ARS</span> <strong>et</strong> à la <span class=\"kw-def\">DDPP</span> ; <span class=\"kw-def\">notification</span> différée sur formulaire dédié.<br><strong>Conserver :</strong> tous <span class=\"kw-clinique\">les</span> restes des derniers repas à <span class=\"kw-chiffre\">4 °C</span> (<span class=\"kw-ci\">pas au congélateur</span>) pour la DDPP.<br><strong>Urgences vitales :</strong> <span class=\"kw-alerte\">botulisme</span> (paralysie respiratoire) et <span class=\"kw-alerte\">SHU à EHEC</span> de l’enfant.</p>","hospit":"<p><strong>Principe :</strong> la majorité des TIAC sont bénignes et prises en charge en <strong>ambulatoire</strong> ; l’<span class=\"kw-alerte\">hospitalisation</span> se discute sur la tolérance et le <span class=\"kw-def\">terrain</span>.</p><ul><li><span class=\"kw-alerte\">Hospitalisation</span> à <strong>discuter</strong> en cas de <span class=\"kw-clinique\">forte intolérance à la prise alimentaire</span> et de <span class=\"kw-clinique\">perte de poids importante</span> (surtout l’<span class=\"kw-clinique\">enfant</span>).</li><li><span class=\"kw-alerte\">Botulisme</span> : <span class=\"kw-ttt\">hospitalisation</span> systématique ; <span class=\"kw-ttt\">réanimation</span> si atteinte respiratoire.</li><li><span class=\"kw-alerte\">SHU à EHEC</span> de l’enfant : <span class=\"kw-ttt\">hospitalisation</span>, recours à l’<span class=\"kw-ttt\">épuration extra-rénale</span> si IRA oligoanurique.</li><li>Intoxication <span class=\"kw-etio\">histaminique</span> : régression rapide → prise en charge <strong>ambulatoire</strong>.</li><li>En milieu hospitalier, invest<span class=\"kw-chiffre\">iga</span>tion conduite avec l’<span class=\"kw-def\">équipe opérationnelle d’hygiène (EOH)</span>.</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Diarrhée sanglante</span> chez l’<span class=\"kw-clinique\">enfant de &lt; 5 ans</span> → risque de <span class=\"kw-alerte\">SHU</span> (EHEC O157:H7).</li><li><span class=\"kw-bio\">Anémie hémolytique</span> + <span class=\"kw-bio\">thrombopénie</span> + <span class=\"kw-alerte\">IRA oligoanurique</span> (microangiopathie <span class=\"kw-etio\">thrombotique</span> du SHU).</li><li><span class=\"kw-alerte\">Paralysie descendante</span> atteignant <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">muscles respiratoires</span> (botulisme).</li><li><span class=\"kw-alerte\">Déshydratation</span> avec <span class=\"kw-ci\">intolérance</span> alimentaire totale, surtout chez l’<span class=\"kw-clinique\">enfant</span>.</li><li><span class=\"kw-clinique\">Femme enceinte</span> ou <span class=\"kw-clinique\">immunodéprimé</span> → formes graves de <span class=\"kw-etio\">listériose</span> (atteinte neuroméningée, fausse couche).</li></ul>","principes":"<p><strong>Principe :</strong> prise en charge avant tout <span class=\"kw-ttt\">symptomatique</span> ; l’<span class=\"kw-ci\">antibiothérapie n’est pas indiquée en 1ʳᵉ intention</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">antidiarrhéiques sont à éviter, voire contre-indiqués</span>.</p><ul><li><span class=\"kw-ttt\">Réhydratation</span> adaptée : apports <span class=\"kw-ttt\">sodés</span> et <span class=\"kw-ttt\">sucrés</span>.</li><li>Lutte contre <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">nausées</span> et <span class=\"kw-clinique\">vomissements</span> ; <span class=\"kw-ttt\">antipyrétique</span> si nécessaire.</li><li><span class=\"kw-ttt\">Antispasmodiques</span> et <span class=\"kw-ttt\">pansements digestifs</span> administrés si nécessaire.</li><li><span class=\"kw-bio\">Coproculture</span> : peut être indiquée.</li><li><span class=\"kw-ci\">Antibiothérapie non indiquée en 1ʳᵉ intention</span>.</li><li><span class=\"kw-ci\">Antidiarrhéiques à éviter, voire contre-indiqués</span>.</li></ul><p><strong><span class=\"kw-etio\">Botulisme</span></strong></p><ul><li><span class=\"kw-ttt\">Hospitalisation</span> + traitement <span class=\"kw-ttt\">symptomatique</span>.</li><li>Si atteinte respiratoire : <span class=\"kw-ttt\">réanimation</span> + <span class=\"kw-ttt\">sérothérapie</span> (antitoxine botulinique).</li></ul><p><strong>Intoxication <span class=\"kw-etio\">histaminique</span></strong></p><ul><li>Régression rapide, accélérée par <span class=\"kw-ttt\">antihistaminiques</span> et <span class=\"kw-ttt\">corticoïdes</span>.</li></ul><p><strong><span class=\"kw-etio\">EHEC</span> / <span class=\"kw-def\">SHU</span> de l’enfant</strong></p><ul><li>Traitement <span class=\"kw-ttt\">symptomatique</span> ; recours parfois à l’<span class=\"kw-ttt\">épuration extra-rénale</span> (dialyse dans <span class=\"kw-chiffre\">50 %</span> des cas).</li></ul>","suivi":"<p><strong>Détecter :</strong> <span class=\"kw-chiffre\">≥ 2 cas</span> groupés (temps, espace) + <span class=\"kw-clinique\">symptomatologie compatible</span> + <strong>origine alimentaire commune</strong>.<br><strong>Investiguer :</strong> trois enquêtes coordonnées par l’<span class=\"kw-def\">ARS</span> / <span class=\"kw-def\">DDPP</span> — <span class=\"kw-def\">clinique-épidémiologique</span>, <span class=\"kw-def\">alimentaire</span>, <span class=\"kw-def\">microbiologique</span>.<br><strong>Conserver :</strong> plats témoins <span class=\"kw-chiffre\">3-5 jours</span> en chambre froide en restauration collective (mesure appliquée seulement si TIAC déclarée).</p><ul><li>Enquête <span class=\"kw-def\">clinique</span> : recensement des cas et indemnes → <span class=\"kw-bio\">taux d’attaque</span> ; <span class=\"kw-bio\">courbe épidémique</span> (un <span class=\"kw-clinique\">pic</span> signe une source ponctuelle).</li><li>Enquête <span class=\"kw-def\">alimentaire</span> : <span class=\"kw-bio\">risque relatif (RR)</span> par étude de cohorte (collectivité &lt; 30) ou <span class=\"kw-bio\">odds ratio (OR)</span> par étude cas-témoins (&gt; 30) — &gt; 1 = aliment suspect.</li><li>Enquête <span class=\"kw-def\">microbiologique</span> : prélèvements patient (<span class=\"kw-bio\">selles</span>, <span class=\"kw-bio\">sang</span>, <span class=\"kw-clinique\">vomissements</span>) et restes/plats témoins ; agent retrouvé dans <span class=\"kw-chiffre\">¼ des TIAC</span> seulement.</li><li><span class=\"kw-def\">Surveillance</span> <span class=\"kw-ttt\">biologique</span> du <span class=\"kw-def\">SHU</span> : <span class=\"kw-bio\">NFS-plaquettes</span>, <span class=\"kw-bio\">schizocytes</span>, <span class=\"kw-bio\">bilan rénal</span>.</li><li>Prévention <em>a posteriori</em> : enquête sanitaire (DDPP / EOH), vérification du système <span class=\"kw-def\">HACCP</span>, actions correctives.</li></ul>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion de TIAC — ≥ 2 cas, même origine alimentaire commune","detail":"<h4>CAT — Orientation étiologique d’une TIAC — Incubation × <span class=\"kw-clinique\">fièvre</span> × type de <span class=\"kw-clinique\">diarrhée</span></h4>","branches":[{"to":"t-botulisme","label":"Signes neuro: diplopie, paralysie descendante, sans fièvre","color":"red"},{"to":"t-histamine","label":"Troubles vasomoteurs (face, cou), céphalées — poisson","color":"blue"},{"to":"q-digestif","label":"Tableau digestif prédominant","color":"green"}]},{"id":"t-botulisme","kind":"terminal","label":"Botulisme","color":"red","detail":"<h4>Clinique</h4><ul><li>Phase d’invasion : <span class=\"kw-clinique\">troubles digestifs</span> transitoires, <span class=\"kw-clinique\">pseudo-presbytie</span>.</li><li>Phase d’état : <span class=\"kw-clinique\">syndrome parasympathicolytique</span> (<span class=\"kw-clinique\">mydriase</span>, sécheresse buccale, <span class=\"kw-clinique\">dysphagie</span>, <span class=\"kw-clinique\">constipation</span>, <span class=\"kw-clinique\">dysurie</span>).</li><li><span class=\"kw-alerte\">Paralysie descendante</span> : nerfs crâniens → membres → muscles respiratoires.</li><li><strong>Absence de <span class=\"kw-clinique\">fièvre</span></strong>, vigilance normale, pas de <span class=\"kw-clinique\">syndrome méningé</span>.</li></ul><h4>Délai</h4><ul><li>Incubation <span class=\"kw-chiffre\">12 à 72 h</span>. Origine : <span class=\"kw-etio\">jambon</span>, <span class=\"kw-etio\">conserves artisanales</span> (toxine préformée).</li></ul><h4>Paraclinique</h4><ul><li>Mise en évidence de la <span class=\"kw-bio\">toxine botulinique</span> (aliment incriminé, voire sang, <span class=\"kw-clinique\">vomissements</span>, selles) ; <span class=\"kw-bio\">électromyographie</span> (bloc de conduction neuromusculaire).</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Hospitalisation</span> + traitement <span class=\"kw-ttt\">symptomatique</span>.</li><li>Si atteinte respiratoire : <span class=\"kw-ttt\">réanimation</span> + <span class=\"kw-ttt\">sérothérapie</span> (antitoxine botulinique).</li></ul>"},{"id":"t-histamine","kind":"terminal","label":"Intoxication histaminique","color":"blue","detail":"<h4>Clinique</h4><ul><li>Troubles <span class=\"kw-clinique\">vasomoteurs</span> (<span class=\"kw-clinique\">érythème facial</span>, face et cou), <span class=\"kw-clinique\">céphalées</span>, troubles digestifs.</li></ul><h4>Délai</h4><ul><li>Incubation <span class=\"kw-chiffre\">très courte (10 min à 1 h)</span>. Origine : <span class=\"kw-etio\">poisson mal conservé</span> (thon, maquereau).</li></ul><h4>Paraclinique</h4><ul><li>Diagnostic <strong>clinique</strong>.</li></ul><h4>Traitement</h4><ul><li>Régression rapide, accélérée par <span class=\"kw-ttt\">antihistaminiques</span> et <span class=\"kw-ttt\">corticoïdes</span>.</li></ul>"},{"id":"q-digestif","kind":"decision","label":"Incubation, fièvre et type de diarrhée ? — Discriminant clé de l’orientation étiologique","branches":[{"to":"q-toxine","label":"Incubation < 24 h, vomissements, SANS fièvre","color":"green"},{"to":"t-noro","label":"Coquillages/crudités, peu fébrile (24-48 h)","color":"green"},{"to":"q-invasif","label":"Incubation > 24 h, fièvre, diarrhée glairosanglante","color":"amber"}]},{"id":"q-toxine","kind":"decision","label":"Aliment en cause ? — Toxine préformée dans l’aliment","branches":[{"to":"t-staph","label":"Pâtisserie, viande manipulée (2-4 h)","color":"green"},{"to":"t-bcereus","label":"Riz, soja à température ambiante","color":"green"},{"to":"t-perfringens","label":"Plats cuisinés la veille (8-24 h)","color":"green"}]},{"id":"t-staph","kind":"terminal","label":"Staphylococcus aureus","color":"green","detail":"<h4>Clinique</h4><ul><li>Début brutal : <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">douleurs abdominales</span>, <span class=\"kw-clinique\">diarrhée</span>, <strong>sans <span class=\"kw-clinique\">fièvre</span></strong>.</li></ul><h4>Délai</h4><ul><li>Incubation <span class=\"kw-chiffre\">2 à 4 h</span> (<span class=\"kw-etio\">toxine thermostable</span> préformée). Origine : pâtisseries, viande manipulée, lait et dérivés ; <span class=\"kw-etio\">porteur sain</span> / staphylococcie cutanée.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Symptomatique</span> : <span class=\"kw-ttt\">réhydratation</span> ; <span class=\"kw-ci\">pas d’antibiothérapie</span>.</li></ul>"},{"id":"t-bcereus","kind":"terminal","label":"Bacillus cereus","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Nausées</span> et <span class=\"kw-clinique\">vomissements</span> (<span class=\"kw-chiffre\">1 à 6 h</span>, toxine émétisante) ou <span class=\"kw-clinique\">diarrhée aqueuse profuse</span> (<span class=\"kw-chiffre\">6 à 12 h</span>, entérotoxine).</li></ul><h4>Délai</h4><ul><li>Origine : <span class=\"kw-etio\">riz</span>, <span class=\"kw-etio\">soja</span> ayant séjourné à température ambiante.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Symptomatique</span> : <span class=\"kw-ttt\">réhydratation</span>.</li></ul>"},{"id":"t-perfringens","kind":"terminal","label":"Clostridium perfringens","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Diarrhée</span> et <span class=\"kw-clinique\">douleurs abdominales</span>, <strong>sans <span class=\"kw-clinique\">fièvre</span></strong>.</li></ul><h4>Délai</h4><ul><li>Incubation <span class=\"kw-chiffre\">8 à 24 h</span>. Origine : <span class=\"kw-etio\">plats cuisinés la veille</span>, réfrigération insuffisante, restauration collective.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Symptomatique</span> : <span class=\"kw-ttt\">réhydratation</span>.</li></ul>"},{"id":"t-noro","kind":"terminal","label":"Norovirus","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Vomissements</span>, <span class=\"kw-clinique\">douleurs abdominales</span>, <span class=\"kw-clinique\">diarrhée</span> peu ou pas fébrile.</li></ul><h4>Délai</h4><ul><li>Incubation <span class=\"kw-chiffre\">24 à 48 h</span>. Origine : <span class=\"kw-etio\">coquillages</span>, <span class=\"kw-etio\">crustacés</span>, <span class=\"kw-etio\">crudités</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Symptomatique</span> : <span class=\"kw-ttt\">réhydratation</span>.</li></ul>"},{"id":"q-invasif","kind":"decision","label":"Terrain et sévérité ? — Tableau entéro-invasif (dysentérique)","branches":[{"to":"t-ehec","label":"Diarrhée sanglante, enfant < 5 ans → SHU","color":"red"},{"to":"t-invasif","label":"Diarrhée fébrile, adulte","color":"amber"}]},{"id":"t-ehec","kind":"terminal","label":"E. coli entérohémorragique (O157:H7)","color":"red","detail":"<h4>Clinique</h4><ul><li>Phase digestive : <span class=\"kw-clinique\">diarrhée sanglante</span> entéro-invasive.</li><li>Phase hématologique : microangiopathie <span class=\"kw-etio\">thrombotique</span> (<span class=\"kw-bio\">anémie hémolytique</span> + <span class=\"kw-bio\">thrombopénie</span>).</li><li>Phase rénale : <span class=\"kw-alerte\">IRA oligoanurique</span> (<span class=\"kw-def\">syndrome hémolytique et urémique</span>).</li></ul><h4>Délai</h4><ul><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-clinique\">enfant de &lt; 5 ans</span> (1ʳᵉ cause d’IRA organique avant <span class=\"kw-chiffre\">3 ans</span>). Origine : produits peu/pas cuits (<span class=\"kw-etio\">lait cru</span>, <span class=\"kw-etio\">viande hachée</span>).</li></ul><h4>Paraclinique</h4><ul><li>Confirmation en <span class=\"kw-bio\">laboratoire spécialisé</span> ; bilan des complications : <span class=\"kw-bio\">NFS-plaquettes</span>, <span class=\"kw-bio\">schizocytes</span>, <span class=\"kw-bio\">bilan rénal</span>.</li></ul><h4>Traitement</h4><ul><li>Traitement <span class=\"kw-ttt\">symptomatique</span> ; recours parfois à l’<span class=\"kw-ttt\">épuration extra-rénale</span> (dialyse dans <span class=\"kw-chiffre\">50 %</span> des cas).</li></ul>"},{"id":"t-invasif","kind":"terminal","label":"TIAC entéro-invasive","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-clinique\">diarrhée afécale glairosanglante</span> + <span class=\"kw-clinique\">douleurs abdominales</span>.</li></ul><h4>Étiologie</h4><ul><li><span class=\"kw-etio\">Salmonella</span> non typhique (<span class=\"kw-chiffre\">12-36 h</span>, volailles, œufs, produits laitiers).</li><li><span class=\"kw-etio\">Campylobacter jejuni</span> (<span class=\"kw-chiffre\">2-5 j</span>, volailles, lait non pasteurisé, eau).</li><li><span class=\"kw-etio\">Shigella</span> (<span class=\"kw-chiffre\">2-5 j</span>, <span class=\"kw-clinique\">syndrome dysentérique</span> franc).</li><li><span class=\"kw-etio\">Yersinia enterocolitica</span> (<span class=\"kw-chiffre\">1-11 j</span>, porc, syndrome pseudo-appendiculaire).</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Symptomatique</span> + <span class=\"kw-ttt\">réhydratation</span> ; <span class=\"kw-bio\">coproculture</span> indiquée ; <span class=\"kw-ci\">antibiothérapie non systématique en 1ʳᵉ intention</span>, <span class=\"kw-ci\">antidiarrhéiques à éviter</span>.</li></ul>"}]},"cards":[{"i":"0a1a6984db75","n":179,"o":"179-11","u":"Définition","t":"Connaître les mesures de prévention des TIAC","q":"Quelles sont les règles d'hygiène essentielles à respecter pour la prévention des TIAC, concernant les lieux, le transport, les cuisines et le personnel ?","a":"<ul><li><strong>Lieux</strong> : Maintenir l'hygiène sur les lieux d'abattage, de pêche et de récolte.</li><li><strong>Transport</strong> : Respecter strictement la <strong>chaîne du froid</strong>.</li><li><strong>Cuisines</strong> : Appliquer le principe de la <strong>« marche en avant »</strong>, évitant tout contact entre le secteur propre (préparation) et le secteur souillé.</li><li><strong>Personnel</strong> : Assurer l'<strong>éducation sanitaire</strong> de toute la chaîne alimentaire.</li></ul>"},{"i":"20e945925c2f","n":179,"o":"179-11","u":"Définition","t":"Connaître les mesures de prévention des TIAC","q":"Quelles mesures de surveillance du personnel sont préconisées pour prévenir les TIAC ?","a":"<p>La surveillance du personnel implique une <strong>surveillance médicale</strong>. Elle comprend notamment l'<strong>éviction</strong> des sujets présentant une infection cutanée, pharyngée ou digestive, afin d'éviter la contamination des aliments.</p>"},{"i":"311b04630f14","n":179,"o":"179-11","u":"Définition","t":"Connaître les mesures de prévention des TIAC","q":"Quelles mesures classiques ne sont PAS considérées comme des mesures de prévention primaire des TIAC ?","a":"<p>Ne sont <strong>PAS</strong> des mesures de prévention primaire des TIAC (car appliquées seulement si une TIAC est avérée/déclarée) :</p><ul><li>La <strong>garde d'un repas témoin</strong> en collectivité.</li><li>La <strong>notification des cas à l'ARS</strong>.</li></ul>"},{"i":"549a1db8b3b8","n":179,"o":"179-11","u":"Définition","t":"Connaître les mesures de prévention des TIAC","q":"Quelles sont les trois axes principaux de la prévention des TIAC selon les autorités de santé ?","a":"<p>La prévention des TIAC repose sur :</p><ul><li>La <strong>surveillance du personnel</strong>.</li><li>L'application de <strong>règles d'hygiène</strong> strictes.</li><li>Le <strong>contrôle de la restauration collective</strong>.</li></ul>"},{"i":"9db224faae36","n":179,"o":"179-11","u":"Définition","t":"Connaître les mesures de prévention des TIAC","q":"Comment est organisé le contrôle des aliments en restauration collective pour prévenir les TIAC et quel système est utilisé ?","a":"<p>Le contrôle passe par des <strong>analyses microbiologiques systématiques</strong> d'échantillons des aliments servis, réalisées par l'<strong>ARS</strong>, les <strong>DSV</strong> (services vétérinaires) et la <strong>DGCCRF</strong>. Le système <strong>HACCP</strong> (Hazard Analysis Critical Control Point) est une mesure préventive (a priori) essentielle dont la mise en place est vérifiée lors des enquêtes sanitaires.</p>"},{"i":"504aa15ad776","n":179,"o":"179-3","u":"Définition","t":"Savoir préciser les principaux risques liés à la consommation d’eau","q":"Quels sont les types de risques physiques spécifiques liés à la consommation d'eau ?","a":"<p>Les risques physiques spécifiques liés à l'eau sont :</p><ul><li>Les <strong>brûlures</strong> : à l'eau chaude, particulièrement chez l'enfant de 1 à 4 ans, souvent suite à des accidents domestiques.</li><li>Les <strong>noyades</strong> : en eau douce ou en eau de mer, lors d'activités de loisir ou professionnelles.</li><li>Les risques liés à l'<strong>activité subaquatique</strong> : en plongée de loisir ou professionnelle.</li></ul>"},{"i":"7883afc953f1","n":179,"o":"179-3","u":"Définition","t":"Savoir préciser les principaux risques liés à la consommation d’eau","q":"Quels sont les types de risques chimiques spécifiques liés à la consommation d'eau ?","a":"<p>Les risques chimiques spécifiques liés à l'eau comprennent :</p><ul><li>Les <strong>pollutions minérales</strong> : éléments nocifs en excès comme les <strong>métaux lourds</strong> (plomb, mercure, arsenic, chrome) pouvant entraîner saturnisme, neurotoxicité ou cancérogenèse.</li><li>Les <strong>pollutions organiques</strong> : notamment les <strong>pesticides</strong> et les <strong>nitrites</strong>, pouvant causer une méthémoglobinémie.</li></ul>"},{"i":"a0d6dc683588","n":179,"o":"179-3","u":"Définition","t":"Savoir préciser les principaux risques liés à la consommation d’eau","q":"Quels sont les types de risques infectieux spécifiques liés à la consommation d'eau ?","a":"<p>Les risques infectieux spécifiques liés à l'eau incluent :</p><ul><li><strong>Bactéries</strong> : <em>Salmonella typhi/paratyphi</em> (typhoïde), <em>Vibrio cholerae</em> (choléra), <em>E. coli</em>, <em>Shigella</em>, <em>Campylobacter</em>, <em>Yersinia</em>.</li><li><strong>Virus</strong> : hépatites A et E, rotavirus, norovirus.</li><li><strong>Parasites</strong> : amœbose, cryptosporidiose, giardiose.</li><li><strong>ATNC</strong> : prions.</li></ul><p>Il faut retenir que la <strong>diarrhée</strong> est une conséquence fréquente des pathologies hydriques et constitue la <strong>2<sup>e</sup> cause de mortalité de l'enfant de moins de 5 ans</strong>.</p>"},{"i":"ef335839ccbd","n":179,"o":"179-3","u":"Définition","t":"Savoir préciser les principaux risques liés à la consommation d’eau","q":"Quels sont les principaux types de risques sanitaires généraux liés à l'eau et à l'alimentation ?","a":"<p>On distingue quatre principaux types de risques sanitaires généraux :</p><ul><li><strong>Biologiques</strong> : bactériens, viraux, parasitaires, fongiques, ATNC (Agents Transmissibles Non Conventionnels comme les prions).</li><li><strong>Physiques</strong> : noyades, brûlures, radioactivité, phénomènes naturels.</li><li><strong>Chimiques</strong> : nitrates, métaux lourds, pesticides, additifs.</li><li><strong>Autres</strong> : allergies, troubles nutritifs, réservoir de vecteurs.</li></ul>"},{"i":"05825a41be8b","n":179,"o":"179-5","u":"Définition","t":"Connaître les mesures de prévention des risques sanitaires liés à l’eau","q":"Quel organisme est responsable de la surveillance de la qualité de l'eau en France ?","a":"<p>En France, la surveillance de la qualité de l'eau est assurée par l'<strong>ARS</strong> (Agence Régionale de Santé), avec des analyses réalisées par des laboratoires agréés <strong>Cofrac</strong>.</p>"},{"i":"598bcbfc28d3","n":179,"o":"179-5","u":"Définition","t":"Connaître les mesures de prévention des risques sanitaires liés à l’eau","q":"Comment l'eau destinée à la consommation humaine est-elle définie comme potable selon les critères microbiologiques ?","a":"<p>L'eau est considérée potable microbiologiquement si elle présente l'<strong>absence</strong> de <strong>coliformes</strong> (dont <em>E. coli</em>), d'<strong>entérocoques</strong> et de <strong>bactéries sulfito-réductrices</strong>.</p>"},{"i":"a8640f43faa8","n":179,"o":"179-5","u":"Définition","t":"Connaître les mesures de prévention des risques sanitaires liés à l’eau","q":"Quels sont les trois axes prioritaires de prévention des risques sanitaires liés à l'eau potable ?","a":"<ul><li>L'<strong>assainissement</strong> : collecte, traitement et évacuation des déchets liquides et solides, y compris les déchets physiologiques humains.</li><li>La <strong>garantie de la potabilité</strong> : protection des réserves naturelles et gestion optimale du cycle de l'eau.</li><li>Le <strong>contrôle de la potabilité</strong> : respect des normes nationales et internationales, contrôles réglementaires à toutes les étapes.</li></ul>"},{"i":"3c8ab2312b0b","n":179,"o":"179-6","u":"Définition","t":"Savoir préciser les principaux risques liés à l’alimentation","q":"Quels sont les différents types de risques associés à la salubrité alimentaire ?","a":"<p>Les risques associés à la salubrité alimentaire sont :</p><ul><li>Le <strong>risque infectieux</strong> : conventionnel (<strong>bactérien, parasitaire, fongique, viral, toxinique</strong>) ou non conventionnel (<strong>prion</strong>).</li><li>Le <strong>risque chimique</strong> : lié aux additifs, polluants, antibiotiques, toxiques.</li><li>Le <strong>risque physique</strong> : lié à la radioactivité.</li></ul>"},{"i":"6320a0618f69","n":179,"o":"179-6","u":"Définition","t":"Savoir préciser les principaux risques liés à l’alimentation","q":"Quels sont les deux principaux types de risques sanitaires liés à l'alimentation selon l'objectif Rank A ?","a":"<p>Les deux principaux types de risques sanitaires alimentaires sont :</p><ul><li>Les risques liés à la <strong>nutrition</strong>.</li><li>Les risques liés à la <strong>salubrité alimentaire</strong>.</li></ul>"},{"i":"df753cf6edac","n":179,"o":"179-6","u":"Définition","t":"Savoir préciser les principaux risques liés à l’alimentation","q":"Quels sont les exemples de troubles nutritifs associés aux risques liés à la nutrition selon l'objectif Rank A ?","a":"<p>Les troubles nutritifs mentionnés sont :</p><ul><li>L'<strong>obésité</strong>.</li><li>L'<strong>anorexie</strong>.</li><li>Les <strong>allergies alimentaires</strong>.</li></ul>"},{"i":"6aa3f76560b1","n":179,"o":"179-7","u":"Définition","t":"Savoir définir une toxi-infection alimentaire collective (TIAC) et connaître les différentes symptomatologies de TIAC","q":"Quelle est la définition d'une toxi-infection alimentaire collective (TIAC) ?","a":"<p>Une toxi-infection alimentaire collective (TIAC) se définit par l'apparition d'au moins <strong>deux cas</strong> d'une symptomatologie, en général digestive, dont on peut rapporter la cause à une <strong>même origine alimentaire</strong>. C'est une <strong>maladie à déclaration obligatoire (MDO)</strong>.</p>"},{"i":"b359e715db06","n":179,"o":"179-7","u":"Définition","t":"Savoir définir une toxi-infection alimentaire collective (TIAC) et connaître les différentes symptomatologies de TIAC","q":"Citez les principales symptomatologies cliniques des TIAC et les agents pathogènes associés.","a":"<p>Les principales symptomatologies cliniques des TIAC sont :</p><ul><li><strong>Entéro-toxinogène (cholériforme)</strong> : diarrhée liquide abondante + vomissements + absence de fièvre. Incubation courte (quelques heures). Germes associés : <strong>Norovirus, C. perfringens, B. cereus, E. coli entérotoxinogène</strong>.</li><li><strong>Entéro-invasif (dysentérique)</strong> : fièvre + diarrhée afécale glairosanglante + douleurs abdominales. Incubation longue (24 à 72 h). Germes associés : <strong>Salmonella, Campylobacter jejuni, Vibrio parahaemolyticus, E. coli entéro-invasif, Yersinia, Shigella</strong>.</li><li><strong>Hépatite aiguë</strong> : tableau d'hépatite virale aiguë. Agents associés : <strong>VHA, VHE</strong>.</li><li><strong>Expression extradigestive / neurologique</strong> : manifestations cutanées (érythème, bouffées vasomotrices) ou neurologiques (botulisme : diplopie, paralysie flasque descendante). Agents associés : <strong>C. botulinum, neurotoxines de dinoflagellés, histamine</strong> (poisson avarié).</li></ul>"},{"i":"e43d58f35762","n":179,"o":"179-7","u":"Définition","t":"Savoir définir une toxi-infection alimentaire collective (TIAC) et connaître les différentes symptomatologies de TIAC","q":"Quelles sont les principales causes des TIAC ?","a":"<p>Les causes des TIAC sont la consommation d'aliments contaminés soit par :</p><ul><li>Des <strong>bactéries, virus ou parasites</strong>.</li><li>Des <strong>toxines bactériennes</strong> (produites soit dans l'aliment avant ingestion, soit dans la lumière digestive après ingestion).</li></ul>"},{"i":"0f8b2ecea641","n":179,"o":"179-8","u":"Étiologies","t":"Connaître les agents pathogènes responsable de TIAC","q":"Quels sont les agents entéro-toxinogènes responsables de TIAC et leurs caractéristiques cliniques?","a":"<p>Les agents entéro-toxinogènes responsables de TIAC, agissant par toxine préformée, se caractérisent par une incubation plutôt courte et <strong>l'absence de fièvre</strong>. Il s'agit de :</p><ul><li><strong>Staphylococcus aureus</strong> (2 à 4 h) : vomissements, douleurs abdominales, diarrhée.</li><li><strong>Clostridium perfringens</strong> (8 à 24 h) : diarrhée aiguë, absence de fièvre.</li><li><strong>Bacillus cereus</strong>.</li></ul>"},{"i":"1a2ec63f16dd","n":179,"o":"179-8","u":"Étiologies","t":"Connaître les agents pathogènes responsable de TIAC","q":"Quelles sont les spécificités de la TIAC à E. coli entérohémorragique (O157:H7) chez l'enfant?","a":"<p>La TIAC à <strong>E. coli entérohémorragique (O157:H7)</strong> est une urgence, particulièrement chez l'enfant de <strong>moins de 5 ans</strong>, étant la <strong>première cause d'insuffisance rénale aiguë organique avant 3 ans</strong>. Elle évolue en 3 phases :</p><ul><li>Phase digestive : <strong>diarrhée sanglante</strong>.</li><li>Phase hématologique : <strong>microangiopathie thrombotique</strong> (anémie hémolytique, thrombopénie).</li><li>Phase rénale : <strong>insuffisance rénale aiguë oligo-anurique</strong>, nécessitant une dialyse dans 50% des cas.</li></ul><p>La prévention repose sur l'interdiction des laitages non pasteurisés et des viandes crues avant 5 ans.</p>"},{"i":"2fecc3a3f7c6","n":179,"o":"179-8","u":"Étiologies","t":"Connaître les agents pathogènes responsable de TIAC","q":"Quels sont les agents entéro-invasifs responsables de TIAC et leurs caractéristiques cliniques?","a":"<p>Les agents entéro-invasifs responsables de TIAC, avec une incubation plus longue et potentiellement une fièvre, sont :</p><ul><li><strong>Salmonella enterica non typhi</strong> (12 à 24 h) : diarrhée aiguë fébrile.</li><li><strong>Shigella</strong>.</li><li><strong>Campylobacter jejuni</strong>.</li><li><strong>Yersinia enterocolitica</strong>.</li><li><strong>Listeria</strong>.</ul><p>Ils se manifestent généralement par une <strong>diarrhée glairo-sanglante</strong> avec de la fièvre.</p>"},{"i":"355267eee232","n":179,"o":"179-8","u":"Étiologies","t":"Connaître les agents pathogènes responsable de TIAC","q":"Quelle est la présentation clinique caractéristique du botulisme lors d'une TIAC due à Clostridium botulinum?","a":"<p>Le botulisme, causé par <strong>Clostridium botulinum</strong> après une incubation de <strong>12 à 72 heures</strong>, se caractérise par :</p><ul><li>Un <strong>syndrome parasympathicolytique</strong> : mydriase, sécheresse buccale, dysphagie, constipation, dysurie.</li><li>Une <strong>paralysie descendante</strong>.</li></ul><p>Il est crucial de noter <strong>l'absence de fièvre</strong>, une vigilance normale et l'absence de syndrome méningé. Une <strong>réanimation</strong> et une <strong>sérothérapie</strong> sont indiquées en cas d'atteinte respiratoire.</p>"},{"i":"dec9f4a36a66","n":179,"o":"179-8","u":"Étiologies","t":"Connaître les agents pathogènes responsable de TIAC","q":"Quels agents pathogènes de TIAC ont une incubation courte (inférieure à 6 heures) et sont plutôt caractérisés par des vomissements?","a":"<p>Un agent typique de cette catégorie est <strong>Staphylococcus aureus</strong>, avec une incubation de <strong>2 à 4 heures</strong>, provoquant <strong>vomissements</strong>, douleurs abdominales et diarrhée, généralement sans fièvre. L'intoxication histaminique, bien que non infectieuse, a une incubation encore plus courte (<strong>10 min à 1h</strong>) avec troubles vasomoteurs, céphalées et troubles digestifs.</p>"},{"i":"06992f6c26f2","n":179,"o":"179-9","u":"Définition","t":"Connaître les modalités de détection et de signalement d’une suspicion de TIAC","q":"Quelle est la différence fondamentale entre le 'signalement' et la 'notification' d'une TIAC, un piège classique ?","a":"Le piège classique est de confondre le signalement et la notification :<ul><li>Le <strong>signalement</strong> est une procédure d'<strong>urgence</strong>, immédiate, réalisée par tout moyen.</li><li>La <strong>notification</strong> est <strong>différée</strong> et s'effectue sur un formulaire dédié à l'ARS.</li></ul>"},{"i":"6c7fb2d14f71","n":179,"o":"179-9","u":"Définition","t":"Connaître les modalités de détection et de signalement d’une suspicion de TIAC","q":"Après le signalement initial d'une TIAC, quelle est la procédure complémentaire à effectuer et quelle mesure pratique doit être prise concernant les repas ?","a":"Après le signalement initial, il faut :<ul><li>Procéder à la <strong>notification de la déclaration</strong> via un formulaire dédié à l'ARS.</li><li><strong>Conserver tous les restes des derniers repas à 4 °C</strong> pour les mettre à disposition de la DDPP.</li></ul>"},{"i":"9ee817b344be","n":179,"o":"179-9","u":"Définition","t":"Connaître les modalités de détection et de signalement d’une suspicion de TIAC","q":"À qui doit-on signaler sans délai une suspicion de TIAC et par quel moyen ?","a":"Le signalement d'une suspicion de TIAC doit être fait <strong>sans délai et par tout moyen approprié</strong> (téléphone, fax) :<ul><li>Au <strong>médecin de l'ARS</strong> (Agence Régionale de Santé).</li><li>À la <strong>DDPP</strong> (Direction Départementale de la Protection des Populations).</li></ul>"},{"i":"f3200b05b2c9","n":179,"o":"179-9","u":"Définition","t":"Connaître les modalités de détection et de signalement d’une suspicion de TIAC","q":"Quels sont les trois éléments à réunir pour détecter une suspicion de TIAC (Toxi-Infection Alimentaire Collective) ?","a":"Pour détecter une suspicion de TIAC, il faut réunir :<ul><li>Une <strong>symptomatologie compatible</strong> (digestive ± extradigestive).</li><li>Au moins <strong>2 cas groupés</strong> dans le temps et l'espace.</li><li>Une <strong>origine alimentaire commune</strong>.</li></ul>"}]};